message.content:
{
  "css": ".booking-host-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  color: #202024;
}

.booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: #60606a;
  margin-top: 4px;
}

.booking-icon-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

.booking-icon-btn img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  pointer-events: none;
}

.booking-icon-btn:hover {
  background-color: #e8e8ed;
}

.booking-icon-btn:active {
  transform: scale(0.96);
}

.booking-icon-btn[aria-pressed="true"] {
  background-color: #eef0fc;
}

.booking-primary-btn {
  min-height: 52px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border-radius: 6px;
  border: none;
  white-space: nowrap;
  overflow-wrap: break-word;
  word-break: keep-all;
  text-align: center;
}

.booking-note {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: #60606a;
  margin-top: 12px;
}"
}
